function union_table(unions: UnionSig[]): UnionTable {
  let head = util.minus_ones(sig_buckets());
  let vnames: string[] = [];
  let vowner: i32[] = [];
  for u in 0..unions.len() {
    let vs = unions[u].variants;
    for v in 0..vs.len() {
      vnames = vnames.append(vs[v]);
      vowner = vowner.append(u);
    }
  }
  let next = util.minus_ones(vnames.len());
  let lib_head = head;
  let lib_next = next;
  let bnames: string[] = [];
  for b in 0..vnames.len() {
    bnames = bnames.append(unprefixed_variant(vnames[b], unions[vowner[b]].module));
  }
  let bhead = head;
  let bnext = next;
  let k = vnames.len() - 1;
  while (k >= 0) {
    let bk = util.hash_bucket(vnames[k], 4093);
    next = next.with(k, head[bk]);
    head = head.with(bk, k);
    if (!declared_by_entry(unions[vowner[k]])) {
      lib_next = lib_next.with(k, lib_head[bk]);
      lib_head = lib_head.with(bk, k);
    }
    let bb = util.hash_bucket(bnames[k], 4093);
    bnext = bnext.with(k, bhead[bb]);
    bhead = bhead.with(bb, k);
    k -= 1;
  }
  let names: string[] = [];
  for m in 0..unions.len() {
    names = names.append(unions[m].name);
  }
  return UnionTable { unions: unions, vnames: vnames, vowner: vowner, index: util.name_index(names), head: head, next: next, lib_head: lib_head, lib_next: lib_next, from_import: false, bnames: bnames, bhead: bhead, bnext: bnext, view_memo: new_view_memo() };
}

